package main

const jsResearchProgressive = `
const researchProbeStages={SEMANTIC_PROBE:'小型語意題',TOOL_PROBE:'工具格式題'};
const researchProbeStates={BEHAVIOR_OBSERVED:'已觀測題目結果',REUSED_LOCAL_BENCHMARK:'重用本機題目紀錄',REUSED_NORMAL_TOOL_TRAFFIC:'重用日常工具觀測',AVAILABILITY_NOT_ESTABLISHED:'尚無有效成功觀測',TOOL_CAPABILITY_NOT_ENABLED:'尚未確認工具能力',CUSTOM_PROTOCOL_CONDITIONS_UNAVAILABLE:'自訂協定尚無可比較條件',REQUEST_FAILED:'本次請求未成功',REQUEST_CANCELLED:'已取消，保留用量與原請求',REQUEST_INTERRUPTED:'已中斷，保留用量與原請求'};
function syncResearchCandidateSelect(select,selected=null){const previous=new Set(selected??[...select.selectedOptions].map(o=>o.value));select.replaceChildren();for(const c of researchCandidates){if(!c.website)continue;option(select,c.id,(c.model_id==='UNKNOWN'?'未確認模型':c.model_id)+' · '+(researchStates[c.state]||c.state)+' · '+c.website);select.lastChild.selected=previous.delete(c.id);}for(const id of previous){option(select,id,id+' · 候選待確認');select.lastChild.selected=true;}}
function syncProgressiveResearchEditors(){syncResearchCandidateSelect($('research-run-candidates'));syncResearchCandidateSelect($('research-schedule-candidates'));syncResearchDeeperEditor();}
function syncResearchDeeperEditor(selected=null){const form=$('research-schedule-form'),select=form.elements.deeper_selections,previous=selected??[...select.selectedOptions].map(o=>JSON.parse(o.value)),pending=new Map(previous.map(v=>[key(v),v]));select.replaceChildren();for(const o of form.elements.private_selections.selectedOptions){const v=JSON.parse(o.value);option(select,o.value,o.textContent);select.lastChild.selected=pending.delete(key(v));}for(const v of pending.values()){option(select,JSON.stringify(v),v.model_id+' / '+v.provider_id+' / '+v.account_id+' / '+v.credential_id+' · 不在目前選取範圍，請修正');select.lastChild.selected=true;}}
function renderResearchPlanScopes(box,rows){for(const row of rows){const s=row.selection;item(box,s.model_id+' · '+connectionLabel(s),row.origin+' · '+row.operation+' · Key 版本 '+row.credential_version+' · '+s.provider_id+' / '+s.account_id+' / '+s.credential_id+(s.group?' / '+s.group:'')+(row.deeper?' · 包含深入題目':''));}}
async function reviewProgressiveResearch(options){const box=modal('確認逐級研究計畫'),ticket=detailVersion;let reading=false,writing=false;const read=async()=>{if(reading||writing)return;reading=true;box.replaceChildren(el('p','正在核對目前連線與預留額…'));try{const review=await submit('/research/plan',options);if(!detailCurrent(ticket))return;box.replaceChildren();box.append(el('p','先重用有效的本機觀測。只有以下明確選取的連線能發送新驗證；每個深入階段最多一個請求，答錯不會自動重送。'));renderResearchPlanScopes(box,review.scopes);item(box,'本輪上限',review.planned_tasks+' 個任務 · 最多 '+review.http_limit+' 次 HTTP · 最多 '+review.maximum_new_inferences_this_round+' 次新推論（包含 '+review.deeper_probe_tasks+' 個深入任務）。');item(box,'目前每次推論預留',review.reserve_tokens_per_inference+' token / '+review.reserve_usd_per_inference+' USD。這是本機入場預留，實際帳單可能不同；缺回報時保留預留。');item(box,'有效期與限制',review.observation_minutes+' 分鐘 · 小型題目不代表完整能力、最大 Context 或模型身份。每日、逐 Key 與共用池上限仍同時生效。');const problem=el('p');problem.setAttribute('role','status');box.append(problem);action(box,'更新研究計畫',read);action(box,'確認並開始逐級研究',async()=>{if(writing||!detailCurrent(ticket))return;writing=true;try{await submit('/research/start',{...options,review_fingerprint:review.fingerprint});if(detailCurrent(ticket))$('detail').close();await loadResearch();notice('逐級研究已排入佇列');}catch(e){if(detailCurrent(ticket))problem.textContent='尚未開始，請更新研究計畫後重試。 '+e.message;}finally{writing=false;}},false);}catch(e){if(detailCurrent(ticket)){box.replaceChildren();detailState(box,e.message,true,read);}}finally{reading=false;}};await read();}
function bindProgressiveResearch(){
 $('research-schedule-private-selections').addEventListener('change',()=>syncResearchDeeperEditor());
 $('research-run-form').addEventListener('submit',async e=>{e.preventDefault();const f=e.target,selections=f.elements.selection.value?[JSON.parse(f.elements.selection.value)]:[],deeper=f.elements.deeper_probe.checked;try{if(deeper&&(!selections.length||!f.elements.minimal_inference.checked))throw Error('深入驗證需要明確選擇模型連線並勾選小型推論驗證。');const options={source_ids:[...f.elements.source_ids.selectedOptions].map(n=>n.value),selections,candidate_ids:[...f.elements.candidate_ids.selectedOptions].map(n=>n.value),observation_minutes:Number(f.elements.observation_minutes.value),deeper_selections:deeper?selections:[],minimal_inference:f.elements.minimal_inference.checked,search:f.elements.search.checked,search_pages:Number(f.elements.search_pages.value),search_country:f.elements.search_country.value,lmspeed_seeds:f.elements.lmspeed_seeds.checked,refresh_aa:f.elements.refresh_aa.checked,budget:Number(f.elements.budget.value),probe_budget:Number(f.elements.probe_budget.value)};if(deeper){await reviewProgressiveResearch(options);return;}await submit('/research/start',options);await loadResearch();notice('研究已排入佇列');}catch(error){notice(error.message,true);}});
}
function researchProbeCard(parent,r){const card=el('article',undefined,'detail-section research-probe-result');card.dataset.probeStage=r.stage;parent.append(card);card.append(el('h3',researchProbeStages[r.stage]||r.stage),el('p',(researchProbeStates[r.state]||r.state)+' · '+new Date(r.observed_at).toLocaleString()));detailRows(card,[['連線',r.selection.model_id+' / '+r.selection.provider_id+' / '+r.selection.account_id+' / '+r.selection.credential_id+' / '+r.selection.endpoint],['本題得分',r.grade?r.grade.correct+' / '+r.grade.total+'（小型固定題目）':'未知；沒有可評分的本題結果'],['模型身份','仍未證明'],['本輪新增 HTTP／推論',r.additional_http_requests+' / '+r.additional_inference_requests],['原請求輸入／輸出 token',(r.provider_reported_input_tokens??'未知')+' / '+(r.provider_reported_output_tokens??'未知')],['原請求站方回報費用',r.provider_reported_usd==null?'未知':r.provider_reported_usd+' USD'],['套件版本',r.suite_version]]);if(r.reused_report_id)card.append(el('p','保留原題目與成本觀測；本輪重用沒有再次送出該推論。'));const details=el('details');details.append(el('summary','證據與判定限制'),el('p','語意題核對 R-2 的 owner=Mira、總數 19、marker=CEDAR-27；工具題核對函式名稱、總數與 marker。得分不能證明模型身份或最大 Context。'));detailRows(details,[['請求紀錄 ID',r.sample_id||'沒有新增請求'],['請求條件 Hash',r.request_condition_hash||'無法比較'],['原題目紀錄',r.reused_report_id||'本次觀測']]);factsView(details,'保存的完整結果',r);card.append(details);}
function researchProbeHistory(parent,filter,ticket){const section=el('details'),body=el('div'),summary=el('summary','逐級驗證紀錄');section.dataset.researchProbes='true';section.append(summary,el('p','每份結果保留當時的連線與原請求成本。成功或答對題目仍不能證明身份。'),body);parent.append(section);let before=0,loading=false,loaded=false;const list=el('div'),problem=el('p'),controls=el('div',undefined,'actions');body.append(list,problem,controls);const more=action(controls,'讀取更多驗證紀錄',()=>read());more.hidden=true;const refresh=action(controls,'更新驗證紀錄',()=>{before=0;loaded=false;return read(true);});const read=async(reset=false)=>{if(loading||!detailCurrent(ticket))return;loading=true;more.disabled=refresh.disabled=true;try{const response=await api('/research/probes?'+filter+(before?'&before='+before:''));if(!detailCurrent(ticket))return;if(reset||!loaded)list.replaceChildren();for(const r of response.reports)researchProbeCard(list,r);if(!response.reports.length&&!before)list.append(el('p','尚無深入驗證紀錄；可以從研究工作區明確選取連線與深入題目。'));before=response.next_before;more.hidden=!before;loaded=true;problem.textContent='';}catch(e){if(detailCurrent(ticket))problem.textContent='讀取失敗，已顯示的紀錄保留。 '+e.message;}finally{loading=false;more.disabled=refresh.disabled=false;}};section.addEventListener('toggle',()=>{if(section.open&&!loaded)read();});return section;}
function renderResearchRunResources(box,usage){if(!usage)return;const section=detailSection(box,'本輪研究用量');detailRows(section,[['已核准推論',usage.requests+' 次'],['入場與保留用量',usage.accounted_tokens+' token / '+usage.accounted_usd+' USD'],['站方回報完整金額',usage.reported_usd==null?'未知':usage.reported_usd+' USD'],['站方回報已知部分',usage.known_reported_usd+' USD · '+usage.unknown_usd_requests+' 次金額未知']]);section.append(el('p','入場與保留用量用於本機預算；缺回報時不視為零，也不代表站方帳單。重用舊觀測不重扣此輪研究額度。'));}
`
